import asyncio
import os
import sys
from run import run_tasks

CLEANUP_FILE = "/tmp/_ki_cleanup.log"

async def main():
    def make(i):
        def factory():
            async def inner():
                try:
                    await asyncio.sleep(30)
                finally:
                    with open(CLEANUP_FILE, "a") as f:
                        f.write(f"cleaned {i}\n")
                        f.flush()
            return inner()
        return factory

    jobs = [make(i) for i in range(4)]
    await run_tasks(jobs, 4)

if __name__ == "__main__":
    try:
        os.remove(CLEANUP_FILE)
    except FileNotFoundError:
        pass
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        with open(CLEANUP_FILE, "a") as f:
            f.write("main-KI\n")
        sys.exit(130)

